const t = async (name, f) => { try { console.log(name, JSON.stringify(await f())); } catch (e) { console.log(name, 'FAIL', e.code, String(e.message).split('\n')[0].split(process.cwd()).join('.').slice(0, 160)); } };
await t('chalk', async () => { const { default: c, Chalk } = await import('chalk'); return [typeof c.red, new Chalk({ level: 1 }).red('x')]; });
await t('strip-ansi', async () => (await import('strip-ansi')).default('\u001b[31mred\u001b[39m'));
await t('nanoid', async () => (await import('nanoid')).nanoid(10).length);
await t('yaml', async () => (await import('yaml')).parse('a: [1, 2]\nb: {c: d}'));
await t('marked', async () => (await import('marked')).marked.parse('# hi *there*'));
await t('prettier', async () => (await import('prettier')).format('const  x={a:1,b:[1,2]}', { parser: 'babel' }));
await t('lodash-es', async () => (await import('lodash-es')).chunk([1, 2, 3, 4, 5], 2));
await t('lodash-es deep', async () => (await import('lodash-es/debounce.js')).default.name);
await t('uuid', async () => (await import('uuid')).validate((await import('uuid')).v4()));
await t('commander', async () => { const { Command } = await import('commander'); const p = new Command().option('-x, --xx <v>').parse(['node', 'x', '-x', '5']); return p.opts(); });
await t('yargs', async () => { const yargs = (await import('yargs')).default; const { hideBin } = await import('yargs/helpers'); return yargs(hideBin(['node', 'x', '--a', '1'])).parseSync().a; });
await t('date-fns', async () => (await import('date-fns')).format(new Date(0), 'yyyy-MM-dd', {}).length);
await t('date-fns/locale', async () => typeof (await import('date-fns/locale')).de);
await t('zod', async () => (await import('zod')).z.string().min(2).safeParse('a').success);
await t('p-limit', async () => { const pLimit = (await import('p-limit')).default; const l = pLimit(1); return Promise.all([l(() => 1), l(() => 2)]); });
await t('dayjs (cjs)', async () => (await import('dayjs')).default(0).year());
await t('dayjs plugin path', async () => typeof (await import('dayjs/plugin/utc.js')).default);
await t('dayjs plugin extensionless', async () => typeof (await import('dayjs/plugin/utc')).default);
await t('semver (cjs)', async () => (await import('semver')).default.satisfies('1.2.3', '^1.0.0'));
await t('ms', async () => (await import('ms')).default('2h'));
await t('kleur', async () => typeof (await import('kleur')).default.red);
